struct Line { let text:String; let x:CGFloat; let y:CGFloat }
func clean(_ value:String)->String{let result=value.unicodeScalars.filter{![0x202A,0x202B,0x202C,0x202D,0x202E,0x2066,0x2067,0x2068,0x2069].contains(Int($0.value))}.map(String.init).joined().trimmingCharacters(in:.whitespacesAndNewlines);return result.hasPrefix(". ") ? String(result.dropFirst(2)).trimmingCharacters(in:.whitespaces):result}
func lines(_ page:PDFPage)->[Line]{(page.selection(for:page.bounds(for:.mediaBox))?.selectionsByLine() ?? []).compactMap{selection in let raw=selection.string ?? "",text=clean(raw);guard !text.isEmpty else{return nil};let box=selection.bounds(for:page),shift=raw.contains(". ") ? 20.0:0;return Line(text:text,x:box.minX+shift,y:box.minY)}}
