func grouped(_ source:[Line])->String{let groups=Dictionary(grouping:source){Int(round($0.y/3))};var value=groups.keys.sorted(by:>).map{key in groups[key]!.sorted{$0.x>$1.x}.map(\.text).joined(separator:" ")}.joined(separator:" ").replacingOccurrences(of:"  ",with:" ");for(pair)in[("הפ רעה","הפרעה"),("פתוח ים","פתוחים"),("הד ם","הדם"),("אי ז ","איזו "),("לב ה","הלב"),("עיים המ","המעיים")]{value=value.replacingOccurrences(of:pair.0,with:pair.1)};return value}
func answerMap(_ document:PDFDocument)->[Int:String]{guard let page=document.page(at:0)else{return[:]};let source=lines(page),labels=source.filter{$0.x<90&&["א","ב","ג","ד"].contains($0.text)};let marks=source.filter{$0.text.contains("X")&&$0.x>80&&$0.y<550};var result:[Int:String]=[:],seen=Set<String>();for mark in marks{guard let label=labels.min(by:{abs($0.y-mark.y)<abs($1.y-mark.y)}),abs(label.y-mark.y)<3 else{continue};let key="\(Int(mark.x)):\(Int(mark.y))";if seen.contains(key){continue};seen.insert(key);let start=label.x+30,local=Int(round((mark.x-start)/22.8))+1,question=local+(label.y<400 ? 20:0);if question>=1&&question<=30{result[question]=label.text}};return result}

guard CommandLine.arguments.count==5,let exam=PDFDocument(url:URL(fileURLWithPath:CommandLine.arguments[1])),let answers=PDFDocument(url:URL(fileURLWithPath:CommandLine.arguments[2])),let year=Int(CommandLine.arguments[3])else{fatalError("usage: extract-exam-bank exam.pdf answers.pdf year output.json")}
let manual:[Int:[String]]=[
  2015:["ב","ד","א","ד","א","ג","ב","ב","ג","ב","ד","א","א","ג","ד","ב","ב","ד","ד","ד","א","ב","ד","ג","ג","א","ג","א","ג","א"],
