]
let keys:[Int:String]=manual[year].map{Dictionary(uniqueKeysWithValues:$0.enumerated().map{($0.offset+1,$0.element)})} ?? answerMap(answers);print("Verified answer keys: \(keys.count)");var output:[[String:Any]]=[]
for pageIndex in 0..<exam.pageCount{guard let page=exam.page(at:pageIndex)else{continue};let source=lines(page);let markers=source.compactMap{line->(Int,Line)? in guard line.x>470,line.y>60,let n=number(line.text),n>=1,n<=30 else{return nil};return(n,line)}.sorted{$0.1.y>$1.1.y};for(index,item)in markers.enumerated(){let(n,marker)=item;guard let correct=keys[n]else{continue};let lower=index+1<markers.count ? markers[index+1].1.y+3:60;let region=source.filter{$0.y<=marker.y+3&&$0.y>lower&&$0.text != marker.text};let labels=region.filter{line in line.x>470&&["א","ב","ג","ד"].contains(line.text.replacingOccurrences(of:".",with:""))}.sorted{$0.y>$1.y};guard labels.count>=4 else{continue};let question=grouped(region.filter{$0.y>labels[0].y+3&&$0.x<470});var options:[[String:String]]=[];for optionIndex in 0..<4{let upper=labels[optionIndex].y+3,lowerOption=optionIndex+1<labels.count ? labels[optionIndex+1].y+3:lower;let text=grouped(region.filter{$0.x<470&&$0.y<=upper&&$0.y>lowerOption});options.append(["id":["א","ב","ג","ד"][optionIndex],"text":text])};if !question.isEmpty&&options.allSatisfy({!($0["text"] ?? "").isEmpty}){output.append(["id":"western-\(year)-\(n)","year":year,"subject":"רפואה מערבית","topic":"רפואה מערבית","questionNumber":n,"question":question,"options":options,"correctAnswer":correct,"explanation":"","source":"מבחן רפואה מערבית \(year)"])}}}
output.sort{($0["questionNumber"]as!Int)<($1["questionNumber"]as!Int)};let data=try JSONSerialization.data(withJSONObject:output,options:[.prettyPrinted,.withoutEscapingSlashes]);try data.write(to:URL(fileURLWithPath:CommandLine.arguments[4]));print("Extracted \(output.count) verified questions for \(year)")
